def sym_fix3(g, iters=10):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    for _ in range(iters):
        cnt={}
        for i in range(H):
            for j in range(W):
                cnt[i,j]=Counter([g[i][j],g[i][W-1-j],g[H-1-i][j],g[H-1-i][W-1-j]])
        def decided(i,j):
            c=cnt[i,j]; mc=c.most_common()
            return mc[0][1]>mc[1][1] if len(mc)>1 else True
        new=[]
        for i in range(H):
            row=[]
            for j in range(W):
                if decided(i,j):
                    row.append(cnt[i,j].most_common(1)[0][0])
                else:
                    imgs=[(i,W-1-j),(H-1-i,j),(H-1-i,W-1-j)]
                    d=[g[a][b] for a,b in imgs if decided(a,b)]
                    row.append(d[0] if d else g[i][j])
            new.append(row)
        if new==g: break
        g=new
    return g
