def repair(g, iters=5):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    for _ in range(iters):
        bad={(i,j) for i in range(H) for j in range(W) if g[i][j]!=g[H-1-i][W-1-j]}
        if not bad: break
        counts={c:0 for c in {v for row in g for v in row}}
        best=None
        for c in sorted(counts):
            cells=[(i,j) for i in range(H) for j in range(W) if g[i][j]==c and ((i,j) in bad or (i,W-1-j) in bad or (H-1-i,j) in bad)]
            if not cells: continue
            out=[row[:] for row in g]
            for i,j in cells:
                nz=[g[i][W-1-j],g[H-1-i][j],g[H-1-i][W-1-j]]
                nz=[v for v in nz if v!=c]
                if nz: out[i][j]=nz[0]
            s=symcheck(out); score=sum(len(x) for x in s)
            if best is None or score<best[0]: best=(score,out)
        g=best[1]
    return g
